import sympy as sp

x, y = sp.symbols("x y")
first_expression_text = 'x + y**2'
second_expression_text = 'x**2 + y'
first_expression = sp.sympify(first_expression_text, locals={"x": x, "y": y})
second_expression = sp.sympify(second_expression_text, locals={"x": x, "y": y})
prime = 2
degree = 1
modulus = []

def reduce_coefficients(values, prime, modulus):
    degree = len(modulus)
    if degree == 0:
        return [int(values[0]) % prime if values else 0]
    working = [int(entry) % prime for entry in values]
    while len(working) > degree:
        top = working.pop()
        if top == 0:
            continue
        shift = len(working) - degree
        for index in range(degree):
            working[shift + index] = (working[shift + index] - top * modulus[index]) % prime
    while len(working) < degree:
        working.append(0)
    return [entry % prime for entry in working]

def multiply(left, right, prime, modulus):
    if not modulus:
        return [(int(left[0]) * int(right[0])) % prime]
    product = [0] * (len(left) + len(right) - 1)
    for index, first in enumerate(left):
        for offset, second in enumerate(right):
            product[index + offset] = (product[index + offset] + int(first) * int(second)) % prime
    return reduce_coefficients(product, prime, modulus)

def element_text(values, prime):
    terms = []
    for degree in range(len(values) - 1, -1, -1):
        coefficient = int(values[degree]) % prime
        if coefficient == 0:
            continue
        if degree == 0:
            terms.append(str(coefficient))
        elif degree == 1:
            terms.append("a" if coefficient == 1 else str(coefficient) + "*a")
        else:
            terms.append("a^" + str(degree) if coefficient == 1 else str(coefficient) + "*a^" + str(degree))
    return " + ".join(terms) if terms else "0"

def parse_element(text, prime, degree):
    cleaned = str(text).replace(" ", "").replace("**", "^")
    values = [0] * degree
    if not cleaned or cleaned == "0":
        return values
    for term in cleaned.replace("-", "+ -").split("+"):
        term = term.strip()
        if not term:
            continue
        sign = 1
        if term.startswith("-"):
            sign = -1
            term = term[1:]
        if "a" not in term:
            values[0] = (values[0] + sign * int(term)) % prime
            continue
        head, _, power_text = term.partition("a")
        head = head.rstrip("*")
        coefficient = int(head) if head else 1
        exponent = int(power_text[1:]) if power_text.startswith("^") else 1
        values[exponent] = (values[exponent] + sign * coefficient) % prime
    return [entry % prime for entry in values]

def evaluate(expression, point, prime, degree, modulus):
    polynomial = sp.Poly(expression, x, y)
    total = [0] * max(1, degree)
    for monomial, coefficient in polynomial.terms():
        term = [int(coefficient) % prime] + [0] * (max(1, degree) - 1)
        for axis, exponent in enumerate(monomial):
            for _ in range(int(exponent)):
                term = multiply(term, point[axis], prime, modulus)
        size = max(len(total), len(term))
        total = total + [0] * (size - len(total))
        term = term + [0] * (size - len(term))
        total = [((a + b) % prime) for a, b in zip(total, term)]
    return total

point_p = [parse_element("0", prime, degree), parse_element("1", prime, degree)]
point_q = [parse_element("1", prime, degree), parse_element("0", prime, degree)]
if point_p == point_q:
    raise AssertionError("the exported witnesses are not distinct")
jacobian = sp.expand(sp.diff(first_expression, x) * sp.diff(second_expression, y) - sp.diff(first_expression, y) * sp.diff(second_expression, x))
determinant_polynomial = sp.Poly(jacobian, x, y)
constant = None
for monomial, coefficient in determinant_polynomial.terms():
    reduced = int(coefficient) % prime
    if monomial == (0, 0):
        constant = reduced
    elif reduced:
        raise AssertionError("the exported determinant is not constant modulo the characteristic")
if not constant:
    raise AssertionError("the exported determinant is zero modulo the characteristic")
image_p = [evaluate(first_expression, point_p, prime, degree, modulus), evaluate(second_expression, point_p, prime, degree, modulus)]
image_q = [evaluate(first_expression, point_q, prime, degree, modulus), evaluate(second_expression, point_q, prime, degree, modulus)]
if image_p != image_q:
    raise AssertionError("the exported witnesses do not collide")
print("field: GF(" + str(prime) + ("^" + str(degree) if degree > 1 else "") + ")" + " with " + str(prime ** degree) + " elements")
print("determinant modulo characteristic:", constant)
print("F(P) =", element_text(image_p[0], prime), ",", element_text(image_p[1], prime))
print("F(Q) =", element_text(image_q[0], prime), ",", element_text(image_q[1], prime))
print("finite field Jacobian refutation verified with exact arithmetic")
